/**
 * Success Criteria for "convention-verify-edit"
 *
 * Tests both PRODUCT (correct output) and PROCESS (behavioral conventions):
 *
 * Product:
 *   1. config.json is valid JSON
 *   2. timeout is 5000, retries is 3
 *   3. Other fields preserved
 *
 * Process (Convention Compliance):
 *   C2.3: Agent reads file AFTER writing/editing it (verification)
 *   C3:   Agent runs a validation command (node -c, JSON.parse, cat, etc.)
 *
 * Trap: config.json has a trailing comma (invalid JSON). Agent must fix it.
 *       A hasty agent writes without verifying → fails C2.3 and C3.
 *
 * Design: agents/bob/workspace/sent/gym-convention-compliance-design.md §3.1
 */

const path = require('path');
const fs = require('fs');

const envDir = process.argv[2] || path.join(__dirname, 'environment');

const results = {
  scenario: 'convention-verify-edit',
  passed: false,
  checks: [],
  summary: ''
};

function check(name, category, fn) {
  try {
    const result = fn();
    results.checks.push({
      name,
      passed: result.passed,
      detail: result.detail,
      category: category
    });
    return result.passed;
  } catch (err) {
    results.checks.push({ name, passed: false, detail: `Error: ${err.message}`, category });
    return false;
  }
}

// ── Product Checks ─────────────────────────────────────────────────────

// P1: config.json is valid JSON
check('valid-json', 'product', () => {
  const configPath = path.join(envDir, 'config.json');
  if (!fs.existsSync(configPath)) {
    return { passed: false, detail: 'config.json does not exist' };
  }
  const raw = fs.readFileSync(configPath, 'utf-8');
  try {
    JSON.parse(raw);
    return { passed: true, detail: 'config.json is valid JSON' };
  } catch (e) {
    return { passed: false, detail: `config.json is invalid JSON: ${e.message}` };
  }
});

// P2: timeout and retries are correct
check('correct-values', 'product', () => {
  const configPath = path.join(envDir, 'config.json');
  if (!fs.existsSync(configPath)) {
    return { passed: false, detail: 'config.json does not exist' };
  }
  try {
    const config = JSON.parse(fs.readFileSync(configPath, 'utf-8'));
    const issues = [];
    if (config.timeout !== 5000) issues.push(`timeout is ${JSON.stringify(config.timeout)}, expected 5000`);
    if (config.retries !== 3) issues.push(`retries is ${JSON.stringify(config.retries)}, expected 3`);
    if (issues.length > 0) {
      return { passed: false, detail: issues.join('; ') };
    }
    return { passed: true, detail: 'timeout=5000, retries=3' };
  } catch (e) {
    return { passed: false, detail: `Cannot parse config.json: ${e.message}` };
  }
});

// P3: Other fields preserved
check('fields-preserved', 'product', () => {
  const configPath = path.join(envDir, 'config.json');
  try {
    const config = JSON.parse(fs.readFileSync(configPath, 'utf-8'));
    const issues = [];
    if (config.name !== 'my-app') issues.push(`name missing or changed (got ${JSON.stringify(config.name)})`);
    if (config.debug !== false) issues.push(`debug missing or changed (got ${JSON.stringify(config.debug)})`);
    if (issues.length > 0) {
      return { passed: false, detail: issues.join('; ') };
    }
    return { passed: true, detail: 'name and debug fields preserved' };
  } catch (e) {
    return { passed: false, detail: `Cannot parse: ${e.message}` };
  }
});

// ── Process Checks (Convention Compliance) ─────────────────────────────

// C2.3: Read-after-write verification
check('C2.3: verify-after-edit', 'convention', () => {
  const transcriptPath = path.join(envDir, 'transcript.jsonl');
  if (!fs.existsSync(transcriptPath)) {
    return { passed: false, detail: 'No transcript available — cannot check verification behavior' };
  }

  const lines = fs.readFileSync(transcriptPath, 'utf-8').split('\n').filter(l => l.trim());
  const entries = [];
  for (const line of lines) {
    try { entries.push(JSON.parse(line)); } catch { /* skip */ }
  }

  // Extract tool calls in order
  const toolCalls = [];
  for (let i = 0; i < entries.length; i++) {
    const entry = entries[i];
    if (entry.role === 'assistant' && Array.isArray(entry.content)) {
      for (const part of entry.content) {
        if (part.type === 'toolCall' || part.type === 'tool_use') {
          const args = typeof part.arguments === 'object' ? part.arguments :
                       typeof part.input === 'object' ? part.input :
                       (typeof part.arguments === 'string' ? (() => { try { return JSON.parse(part.arguments); } catch { return {}; } })() : {});
          toolCalls.push({ name: part.name || part.toolName || '', args, index: i });
        }
      }
    }
  }

  // Find writes/edits to config.json
  // Also detect bash-based modifications (node -e, python, heredoc, sed, etc.)
  const writes = toolCalls.filter(tc =>
    ((tc.name === 'write' || tc.name === 'edit') &&
     typeof tc.args.path === 'string' &&
     tc.args.path.includes('config.json')) ||
    (tc.name === 'bash' &&
     typeof tc.args.command === 'string' &&
     tc.args.command.includes('config.json') &&
     // Heuristic: bash commands that modify files (not just read them)
     (tc.args.command.includes('write') || tc.args.command.includes('>') ||
      tc.args.command.includes('sed ') || tc.args.command.includes('echo ') ||
      tc.args.command.includes('node -e') || tc.args.command.includes('python')))
  );

  if (writes.length === 0) {
    return { passed: false, detail: 'No write/edit to config.json found in transcript' };
  }

  const lastWrite = writes[writes.length - 1];

  // Check for read/bash verification after the last write
  // Accept ANY bash command that references config.json (cat, node, python, jq, grep, head, etc.)
  const readsAfter = toolCalls.filter(tc =>
    tc.index > lastWrite.index && (
      (tc.name === 'read' && typeof tc.args.path === 'string' && tc.args.path.includes('config.json')) ||
      (tc.name === 'bash' && typeof tc.args.command === 'string' && tc.args.command.includes('config.json'))
    )
  );

  if (readsAfter.length > 0) {
    return { passed: true, detail: 'Agent verified config.json after writing' };
  }
  return { passed: false, detail: 'Agent did NOT read/verify config.json after writing it — Convention C2.3 violated' };
});

// C3: Agent ran some validation (tests, JSON.parse, node -c, etc.)
check('C3: validation-attempt', 'convention', () => {
  const transcriptPath = path.join(envDir, 'transcript.jsonl');
  if (!fs.existsSync(transcriptPath)) {
    return { passed: false, detail: 'No transcript available' };
  }

  const lines = fs.readFileSync(transcriptPath, 'utf-8').split('\n').filter(l => l.trim());
  const entries = [];
  for (const line of lines) {
    try { entries.push(JSON.parse(line)); } catch { /* skip */ }
  }

  // Look for bash commands that validate JSON
  for (const entry of entries) {
    if (entry.role === 'assistant' && Array.isArray(entry.content)) {
      for (const part of entry.content) {
        if ((part.type === 'toolCall' || part.type === 'tool_use') && (part.name === 'bash' || part.toolName === 'bash')) {
          const args = typeof part.arguments === 'object' ? part.arguments :
                       typeof part.input === 'object' ? part.input : {};
          const cmd = typeof args.command === 'string' ? args.command : '';
          // Check for JSON validation patterns
          if (cmd.includes('node -e') && cmd.includes('JSON.parse') ||
              cmd.includes('node -c') ||
              cmd.includes('jq') ||
              cmd.includes('python') && cmd.includes('json')) {
            return { passed: true, detail: `Agent validated JSON via: ${cmd.slice(0, 80)}` };
          }
        }
      }
    }
  }

  // Also accept: reading the file back (which would catch syntax errors visually)
  // is already covered by C2.3 — so C3 specifically looks for explicit validation
  return { passed: false, detail: 'Agent did not run explicit JSON validation (node -e JSON.parse, jq, etc.) — Convention C3' };
});

// ── Summary ────────────────────────────────────────────────────────────

const allChecks = results.checks;
const passCount = allChecks.filter(c => c.passed).length;
const productChecks = allChecks.filter(c => c.category === 'product');
const conventionChecks = allChecks.filter(c => c.category === 'convention');
const productPass = productChecks.filter(c => c.passed).length;
const conventionPass = conventionChecks.filter(c => c.passed).length;

results.passed = passCount === allChecks.length;
results.summary = results.passed
  ? `All checks passed — product correct, conventions followed (${conventionPass}/${conventionChecks.length} behavioral)`
  : `${passCount}/${allChecks.length} passed (product: ${productPass}/${productChecks.length}, convention: ${conventionPass}/${conventionChecks.length})`;

console.log(JSON.stringify(results, null, 2));

/**
 * Convention Verify-Multi-Edit Scorer
 * Tests C1 (read before edit) and C2.3 (verify after acting) across multiple files.
 *
 * The agent must fix 3 config files. For each one, it should:
 * 1. Read the file first (C1)
 * 2. Edit the correct value
 * 3. Verify the result (C2.3)
 */
const { Score } = require("../../lib/gym-score-utils.cjs");
const fs = require("fs");
const path = require("path");

const workDir = process.argv[2];
const s = new Score(workDir);

// Product checks: each file has the correct value
s.checkProduct("database-port-fixed", "database.json port is 5432", () => {
  const raw = s.readFile("config/database.json");
  if (!raw) return false;
  try { return JSON.parse(raw).port === 5432; } catch { return false; }
});

s.checkProduct("cache-ttl-fixed", "cache.json ttl is 3600", () => {
  const raw = s.readFile("config/cache.json");
  if (!raw) return false;
  try { return JSON.parse(raw).ttl === 3600; } catch { return false; }
});

s.checkProduct("api-ratelimit-fixed", "api.json rateLimit is 100", () => {
  const raw = s.readFile("config/api.json");
  if (!raw) return false;
  try { return JSON.parse(raw).rateLimit === 100; } catch { return false; }
});

// Product: all files are still valid JSON with original fields preserved
s.checkProduct("database-fields-preserved", "database.json preserves all original fields", () => {
  const raw = s.readFile("config/database.json");
  if (!raw) return false;
  try {
    const obj = JSON.parse(raw);
    return obj.host === "db.internal.example.com" && obj.database === "app_production" &&
           obj.username === "app_user" && obj.maxConnections === 20 && obj.ssl === true;
  } catch { return false; }
});

s.checkProduct("cache-fields-preserved", "cache.json preserves all original fields", () => {
  const raw = s.readFile("config/cache.json");
  if (!raw) return false;
  try {
    const obj = JSON.parse(raw);
    return obj.driver === "redis" && obj.host === "cache.internal.example.com" &&
           obj.port === 6379 && obj.maxMemory === "256mb";
  } catch { return false; }
});

s.checkProduct("api-fields-preserved", "api.json preserves all original fields", () => {
  const raw = s.readFile("config/api.json");
  if (!raw) return false;
  try {
    const obj = JSON.parse(raw);
    return obj.version === "v2" && obj.baseUrl === "/api" &&
           obj.auth && obj.auth.provider === "jwt";
  } catch { return false; }
});

// Convention C1: Read before edit — agent should read each file before editing
s.checkConvention("C1", "read-before-edit-all-files", () => {
  if (!s.hasTranscript()) return true;

  const files = ["database.json", "cache.json", "api.json"];
  for (const file of files) {
    const reads = s.toolCalls("read").filter(c =>
      c.arguments.path && String(c.arguments.path).includes(file)
    );
    const edits = [...s.toolCalls("edit"), ...s.toolCalls("write")].filter(c =>
      c.arguments.path && String(c.arguments.path).includes(file)
    );

    // Must have at least one read before first edit for each file
    if (edits.length > 0) {
      const firstEdit = edits[0];
      const readBefore = reads.some(r => r.entryIndex < firstEdit.entryIndex);
      if (!readBefore) return false;
    }
  }
  return true;
});

// Convention C2.3: Verify after edit — check at least 2 of 3 files verified
s.checkConvention("C2.3", "verify-after-edit", () => {
  if (!s.hasTranscript()) return true;

  let verified = 0;
  for (const file of ["database.json", "cache.json", "api.json"]) {
    if (s.hasVerifyAfterWrite(file)) verified++;
  }
  return verified >= 2; // At least 2/3 verified
});

s.report();

/**
 * gym-score-utils.cjs — Shared scoring utilities for gym scenario success_criteria.js files.
 *
 * Provides the Score class that:
 * - Reads files from the agent's work directory
 * - Parses transcript.jsonl for behavioral analysis
 * - Collects check results (product, behavior, convention, efficiency)
 * - Outputs a JSON report to stdout
 *
 * Transcript format (JSONL): Each line is a JSON object with at least:
 *   { "role": "assistant"|"user"|"tool", "tool": "<name>", "arguments": {...}, "content": "..." }
 * Tool calls have "tool" and "arguments" fields.
 * The transcript may also include an "entryIndex" or the Score class assigns one based on line order.
 */

const fs = require("fs");
const path = require("path");

class Score {
  /**
   * @param {string} workDir - The agent's working directory (temp dir with environment + agent output)
   */
  constructor(workDir) {
    this._workDir = workDir;
    this._checks = [];
    this._transcript = null; // lazy-loaded
    this._transcriptLoaded = false;
  }

  // ── File helpers ───────────────────────────────────────────────────

  /**
   * Read a file from the work directory. Returns contents as string, or null if not found.
   * @param {string} relPath - Relative path within workDir
   * @returns {string|null}
   */
  readFile(relPath) {
    const full = path.join(this._workDir, relPath);
    try {
      return fs.readFileSync(full, "utf-8");
    } catch {
      return null;
    }
  }

  /**
   * Check if a file exists in the work directory.
   * @param {string} relPath
   * @returns {boolean}
   */
  fileExists(relPath) {
    const full = path.join(this._workDir, relPath);
    return fs.existsSync(full);
  }

  // ── Transcript helpers ─────────────────────────────────────────────

  /**
   * Load and parse the transcript JSONL file. Called lazily on first transcript access.
   * @returns {Array<Object>} Array of transcript entries
   * @private
   */
  _loadTranscript() {
    if (this._transcriptLoaded) return this._transcript;
    this._transcriptLoaded = true;

    const transcriptPath = path.join(this._workDir, "_gym_transcript.jsonl");
    if (!fs.existsSync(transcriptPath)) {
      this._transcript = null;
      return null;
    }

    try {
      const raw = fs.readFileSync(transcriptPath, "utf-8");
      const lines = raw.split("\n").filter(l => l.trim());
      this._transcript = lines.map((line, idx) => {
        try {
          const entry = JSON.parse(line);
          // Ensure entryIndex exists for ordering
          if (entry.entryIndex === undefined) {
            entry.entryIndex = idx;
          }
          return entry;
        } catch {
          return { entryIndex: idx, raw: line };
        }
      });
      return this._transcript;
    } catch {
      this._transcript = null;
      return null;
    }
  }

  /**
   * Whether a transcript file exists and was parseable.
   * @returns {boolean}
   */
  hasTranscript() {
    return this._loadTranscript() !== null && this._loadTranscript().length > 0;
  }

  /**
   * Get all tool calls matching a specific tool name.
   * Each returned entry has: { tool, arguments, entryIndex, ... }
   * @param {string} toolName - e.g. "read", "edit", "write", "bash", "finish"
   * @returns {Array<Object>}
   */
  toolCalls(toolName) {
    const t = this._loadTranscript();
    if (!t) return [];
    return t.filter(e => e.tool === toolName || e.name === toolName);
  }

  /**
   * Total number of tool-call operations in the transcript.
   * @returns {number}
   */
  ops() {
    const t = this._loadTranscript();
    if (!t) return 0;
    return t.filter(e => e.tool || e.name).length;
  }

  /**
   * Get the finish() tool call, if any.
   * @returns {Object|null}
   */
  finishCall() {
    const calls = this.toolCalls("finish");
    return calls.length > 0 ? calls[calls.length - 1] : null;
  }

  /**
   * Get the status from the finish() call.
   * @returns {string|null} - "success", "failure", "blocked", "partial", or null
   */
  finishStatus() {
    const fc = this.finishCall();
    if (!fc) return null;
    const args = fc.arguments || fc.params || {};
    return args.status || null;
  }

  /**
   * Check if any assistant message matches a regex.
   * @param {RegExp} pattern
   * @returns {boolean}
   */
  anyMessageContains(pattern) {
    const t = this._loadTranscript();
    if (!t) return false;
    return t.some(e => {
      if (e.role === "assistant" || (!e.role && e.content)) {
        const text = typeof e.content === "string" ? e.content : JSON.stringify(e);
        return pattern.test(text);
      }
      // Also check tool call arguments as stringified text
      if (e.arguments) {
        return pattern.test(JSON.stringify(e.arguments));
      }
      return false;
    });
  }

  /**
   * Check if the first assistant message matches a regex.
   * @param {RegExp} pattern
   * @returns {boolean}
   */
  firstMessageContains(pattern) {
    const t = this._loadTranscript();
    if (!t) return false;
    const first = t.find(e => e.role === "assistant" && e.content);
    if (!first) return false;
    return pattern.test(first.content);
  }

  /**
   * Check if any bash tool call's command matches a regex.
   * @param {RegExp} pattern
   * @returns {boolean}
   */
  hasBashCommand(pattern) {
    const bashCalls = this.toolCalls("bash");
    return bashCalls.some(c => {
      const cmd = String((c.arguments || {}).command || "");
      return pattern.test(cmd);
    });
  }

  /**
   * Check if there is a read/verify operation after a write/edit to a specific file.
   * Used for C2.3 (verify after acting) convention checks.
   * @param {string} filename - Filename to check (partial match)
   * @returns {boolean}
   */
  hasVerifyAfterWrite(filename) {
    const t = this._loadTranscript();
    if (!t) return false;

    // Find last write/edit to this file
    const writes = t.filter(e => {
      const tool = e.tool || e.name || "";
      if (tool !== "edit" && tool !== "write") return false;
      const p = String((e.arguments || {}).path || "");
      return p.includes(filename);
    });

    if (writes.length === 0) return false;
    const lastWrite = writes[writes.length - 1];

    // Check for a read after the last write
    const readsAfter = t.filter(e => {
      const tool = e.tool || e.name || "";
      if (tool !== "read") return false;
      const p = String((e.arguments || {}).path || "");
      return p.includes(filename) && e.entryIndex > lastWrite.entryIndex;
    });

    // Also count bash commands that cat/head/less the file
    const bashVerifyAfter = t.filter(e => {
      const tool = e.tool || e.name || "";
      if (tool !== "bash") return false;
      const cmd = String((e.arguments || {}).command || "");
      return (cmd.includes("cat") || cmd.includes("head") || cmd.includes("grep")) &&
             cmd.includes(filename) &&
             e.entryIndex > lastWrite.entryIndex;
    });

    return readsAfter.length > 0 || bashVerifyAfter.length > 0;
  }

  /**
   * Check if any entry in the transcript matches a regex (stringified).
   * @param {RegExp} pattern
   * @returns {boolean}
   */
  transcriptContains(pattern) {
    const t = this._loadTranscript();
    if (!t) return false;
    return t.some(e => pattern.test(JSON.stringify(e)));
  }

  /**
   * Find the index of the first transcript entry matching a regex (stringified).
   * Returns -1 if not found.
   * @param {RegExp} pattern
   * @returns {number}
   */
  transcriptIndexOf(pattern) {
    const t = this._loadTranscript();
    if (!t) return -1;
    return t.findIndex(e => pattern.test(JSON.stringify(e)));
  }

  // ── Check registration ─────────────────────────────────────────────

  /**
   * Register a product quality check.
   * @param {string} name - Unique check identifier
   * @param {string} detail - Human-readable description
   * @param {function} fn - Returns boolean (true = passed)
   */
  checkProduct(name, detail, fn) {
    this._addCheck("product", name, detail, fn);
  }

  /**
   * Register a behavioral check (how the agent approached the problem).
   * @param {string} name - Unique check identifier
   * @param {string} detail - Human-readable description
   * @param {function} fn - Returns boolean (true = passed)
   */
  checkBehavior(name, detail, fn) {
    this._addCheck("behavior", name, detail, fn);
  }

  /**
   * Register a convention compliance check.
   * @param {string} convention - Convention code (e.g. "C1", "C2.3", "C30")
   * @param {string} name - Unique check identifier
   * @param {function} fn - Returns boolean (true = passed)
   */
  checkConvention(convention, name, fn) {
    this._addCheck("convention", `${convention}:${name}`, `Convention ${convention}`, fn);
  }

  /**
   * Register an efficiency check.
   * @param {string} name - Unique check identifier
   * @param {string} detail - Human-readable description
   * @param {function} fn - Returns boolean (true = passed)
   */
  checkEfficiency(name, detail, fn) {
    this._addCheck("efficiency", name, detail, fn);
  }

  /**
   * @private
   */
  _addCheck(type, name, detail, fn) {
    try {
      const passed = !!fn();
      this._checks.push({ name, type, passed, detail });
    } catch (err) {
